{
  "claims": [
    {
      "anchor": "Because the wal-index lives in shared memory, all processes using a WAL database must be on the same host",
      "claim_text": "All processes using a WAL database must be on the same host because the wal-index lives in shared memory.",
      "kind": "logic",
      "sure": true,
      "evidence": [
        {"sid": "P1.S3", "rel": "entails"},
        {"sid": "P0.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P1.S3 says shared memory means all readers on same machine; P0.S0 says all processes must be on same host."
    },
    {
      "anchor": "two processes on different machines sharing a database over NFS cannot use WAL",
      "claim_text": "Two processes on different machines sharing a database over NFS cannot use WAL.",
      "kind": "logic",
      "sure": true,
      "evidence": [
        {"sid": "P0.S0", "rel": "entails"},
        {"sid": "P1.S4", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P0.S0 says WAL does not work over network filesystem; P1.S4 says WAL will not work on network filesystem."
    },
    {
      "anchor": "Being on the same host, however, is enough to guarantee that WAL will work",
      "claim_text": "Being on the same host is sufficient to guarantee that WAL will work.",
      "kind": "logic",
      "sure": true,
      "evidence": [
        {"sid": "P0.S0", "rel": "refutes"},
        {"sid": "P5.S2", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "P0.S0 states a necessary condition, not sufficient; P5.S2 shows VFS support also needed."
    },
    {
      "anchor": "Since there is only one WAL file, two writers can never be writing at the same moment",
      "claim_text": "Because there is only one WAL file, two writers can never be writing at the same moment.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P2.S2", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P2.S2 states only one writer at a time due to single WAL file."
    },
    {
      "anchor": "readers can run alongside a writer",
      "claim_text": "Readers can run alongside a writer.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P2.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P2.S1 says writers and readers can run at the same time."
    },
    {
      "anchor": "this single-writer limit can be lifted with BEGIN CONCURRENT",
      "claim_text": "The single-writer limit can be lifted with BEGIN CONCURRENT.",
      "kind": "direct",
      "sure": true,
      "evidence": [],
      "check": null,
      "reasoning": "No passage mentions BEGIN CONCURRENT; unsupported."
    },
    {
      "anchor": "A process can use WAL without shared memory only if it sets EXCLUSIVE locking mode before its first WAL access",
      "claim_text": "A process can use WAL without shared memory only if it sets EXCLUSIVE locking mode before its first WAL access.",
      "kind": "logic",
      "sure": true,
      "evidence": [
        {"sid": "P3.S0", "rel": "entails"},
        {"sid": "P3.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P3.S0 and P3.S1 state this condition."
    },
    {
      "anchor": "in that case it stays in EXCLUSIVE mode until it leaves WAL journal mode",
      "claim_text": "If EXCLUSIVE locking mode is set before first WAL access, the connection stays in EXCLUSIVE mode until it leaves WAL journal mode.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P4.S1", "rel": "entails"},
        {"sid": "P4.S2", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P4.S1 says remains EXCLUSIVE as long as WAL; P4.S2 says only way out is to leave WAL."
    },
    {
      "anchor": "With PRAGMA synchronous=NORMAL, commits skip the WAL sync",
      "claim_text": "With PRAGMA synchronous=NORMAL, commits skip the WAL sync.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P6.S2", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P6.S2 says writers omit sync if synchronous is NORMAL."
    },
    {
      "anchor": "the checkpoint is the only operation that issues a sync",
      "claim_text": "With PRAGMA synchronous=NORMAL, the checkpoint is the only operation that issues a sync.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P7.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P7.S0 states checkpoint is the only operation to issue sync with synchronous NORMAL."
    },
    {
      "anchor": "with FULL, every commit syncs the WAL",
      "claim_text": "With PRAGMA synchronous=FULL, every commit syncs the WAL.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P6.S2", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P6.S2 says writers sync WAL on every commit if synchronous is FULL."
    },
    {
      "anchor": "Running the checkpoint in a separate thread therefore guarantees that the main thread never blocks on a sync, whatever the synchronous setting",
      "claim_text": "Running the checkpoint in a separate thread guarantees that the main thread never blocks on a sync, regardless of the synchronous setting.",
      "kind": "logic",
      "sure": true,
      "evidence": [
        {"sid": "P7.S1", "rel": "refutes"},
        {"sid": "P7.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P7.S1's guarantee is conditional on synchronous=NORMAL; P7.S0 states that condition."
    }
  ]
}
